<?php
declare(strict_types=1);
$config=require dirname(__DIR__).'/config/app.php';
require dirname(__DIR__).'/app/Core/Security.php';require dirname(__DIR__).'/app/Core/Database.php';require dirname(__DIR__).'/app/Core/SchemaInspector.php';require dirname(__DIR__).'/app/Core/WorkflowHelpers.php';require dirname(__DIR__).'/app/Core/AuditLogger.php';require dirname(__DIR__).'/app/Services/Authorization.php';
Security::startSession($config);
if($_SERVER['REQUEST_METHOD']!=='POST'){http_response_code(405);exit('Method not allowed.');}
if(!Security::verifyCsrf($_POST['_csrf']??null)){http_response_code(419);exit('Session expired. Refresh and retry.');}
try{$db=Database::connection();$user=WorkflowHelpers::requireUser($db,$config);if(!Authorization::can($db,$user,'appointments.create'))throw new InvalidArgumentException('Your account cannot request appointments.');
$office=WorkflowHelpers::clean((string)($_POST['office_unit']??''),100);$purpose=WorkflowHelpers::clean((string)($_POST['appointment_purpose']??''),180);$details=WorkflowHelpers::clean((string)($_POST['details']??''),2000);$date=trim((string)($_POST['requested_date']??''));$time=trim((string)($_POST['requested_time']??''));
$offices=['Barangay Hall / General Inquiry','Barangay Secretary','Barangay Captain','Health and Medicine Assistance','Document Processing'];if(!in_array($office,$offices,true)||$purpose===''||!WorkflowHelpers::validDate($date,true)||!preg_match('/^(?:[01]\d|2[0-3]):[0-5]\d$/',$time))throw new InvalidArgumentException('Complete the office, purpose, future date, and valid time.');if($date===date('Y-m-d')&&$time<=date('H:i'))throw new InvalidArgumentException('Choose a time later than the current time.');
$ref=WorkflowHelpers::reference('APT');$db->beginTransaction();$q=$db->prepare("INSERT INTO appointment_requests (reference_code,user_id,office_unit,appointment_purpose,details,requested_date,requested_time,status) VALUES (:ref,:uid,:office,:purpose,:details,:date,:time,'SUBMITTED')");$q->execute(['ref'=>$ref,'uid'=>$user['user_id'],'office'=>$office,'purpose'=>$purpose,'details'=>$details,'date'=>$date,'time'=>$time]);$id=(int)$db->lastInsertId();$h=$db->prepare("INSERT INTO appointment_status_history (appointment_id,old_status,new_status,notes,changed_by_user_id) VALUES (:id,NULL,'SUBMITTED','Initial appointment request',:uid)");$h->execute(['id'=>$id,'uid'=>$user['user_id']]);AuditLogger::record($db,(int)$user['user_id'],'APPOINTMENT_SUBMITTED','appointment',$id,['reference_code'=>$ref]);$db->commit();header('Location: dashboard.php?submitted=1');exit;
}catch(InvalidArgumentException $e){if(isset($db)&&$db instanceof PDO&&$db->inTransaction())$db->rollBack();http_response_code(422);$msg=$e->getMessage();}catch(Throwable $e){if(isset($db)&&$db instanceof PDO&&$db->inTransaction())$db->rollBack();error_log('Appointment submit: '.$e->getMessage());http_response_code(503);$msg='Unable to submit appointment request.';}
require dirname(__DIR__).'/app/Core/PublicPage.php';pageHeader('Appointment not submitted');?><main id="main-content" class="section"><div class="notice warning"><?= Security::e($msg??'Request failed.') ?></div><a class="action-secondary" href="appointment.php">Return to appointments</a></main><?php pageFooter();
